"""Editorial question designs for texts, writing practice, and study skills."""

from review_angle_plans import audit, revise_domain


LITERATURE = """history_origins|A Work's First Context|What publication and social setting shaped one literary work?|Use dated edition, correspondence, and contemporary response.
famous_examples|A Canonical Text Rechecked|What does the text itself support beyond its reputation?|Specify edition and passage.
hidden_stories|Editors and Translators|Whose work changed how a literary work reached readers?|Trace proofs, translation, and credit.
beginner_explainers|Read a Passage Closely|How do speaker, form, and context shape meaning?|Use a short quoted passage within rights limits.
advanced_concepts|Narrator and Reliability|Which textual signals complicate a narrator's account?|Compare scenes and alternative readings.
mysteries_unsolved_cases|An Unsettled Attribution|Which manuscript or publication evidence supports rival claims?|Separate consensus from conjecture.
technology_innovation|A New Reading Medium|How did format change a work's circulation or reception?|Compare dated editions and reader evidence.
people_personalities|Author and Collaborators|Which decisions can be attributed to whom?|Use drafts, letters, editorial records.
major_events|A Work's Publication|What changed between manuscript, first edition, and later versions?|Document text variants.
how_it_works|Text to Edition|How do drafting, editing, printing, and preservation affect a work?|Follow one documented edition.
rise_fall|A Work's Changing Reputation|Which institutions and readers altered its status?|Compare reviews, syllabi, and editions across time.
then_vs_now|Two Readings across Time|How did reception of one passage change?|Use dated, situated critical sources.
future_developments|A New Edition or Adaptation|Which editorial choices require fresh evidence?|Treat proposal as conditional.
myths_vs_facts|An Author Legend Tested|Does a popular biographical story match records?|Trace earliest claim and archive.
documentary_stories|Manuscript to Reader|How did one text pass through drafts, publication, and later use?|Build a dated source trail.
creative_brief|What Was the Work Asked to Do?|Which commission or writer aim is documented?|Distinguish stated intent from interpretation.
materials_and_tools|Writing Materials|How did notebook, typewriter, or printing limits shape text?|Use surviving artifacts and drafts.
process_breakdown|Revision Visible|What changed between two authorized versions?|Compare textual variants, not imagined process.
composition_choice|Form and Meaning|Why does a structural or stylistic choice matter in a passage?|Test with close reading and context.
collaborative_authorship|Many Hands in a Text|How did editor, translator, or performer alter the work?|Attribute changes from records.
adaptation_across_media|Work in a New Medium|Which narrative choices change in film, stage, or audio?|Compare named versions and rights.
audience_reception|Readers at Publication|What do contemporary reviews show and omit?|Sample audiences and publication context.
cultural_context|Text and Its World|Which historical institutions or language conventions matter?|Use period sources without reducing work to context.
preservation_restoration|Saving a Manuscript|Which conservation choices affect what scholars can read?|Use archive description and condition report.
rights_and_attribution|Who May Reproduce a Text?|Which copyright or permission record covers a version?|Name jurisdiction and edition.
style_comparison|Two Texts, Same Criterion|How do two writers handle a formal problem?|Compare passages and period, avoid ranking by taste alone.
creative_failure|A Rejected Draft|What did a writer change after criticism or rejection?|Use dated drafts and correspondence.
field_textual_form|Form on the Page|How do lineation, punctuation, or layout shape reading?|Use exact edition and reproduction.
field_performance_choice|A Text Read Aloud|What does performance reveal or obscure?|Compare attributed recordings and text.
field_audience_history|Who Could Read It?|How did price, literacy, distribution, and censorship shape access?|Use dated evidence.
field_translation_or_adaptation|Meaning across Versions|Which choice changed tone or reference in translation?|Compare source and credited version.
field_critical_reception|A Critical Disagreement|What evidence do two critics read differently?|State arguments and publication dates.
"""

WRITING = """history_origins|A Writing Practice Emerges|Which audience or medium shaped one writing convention?|Use dated examples and guides.
famous_examples|A Draft and Its Final Form|What did revision improve or change?|Compare authorized drafts and intended audience.
hidden_stories|Editors and Writing Partners|Whose feedback or labor shaped a finished piece?|Use credited records and interviews.
beginner_explainers|From Purpose to Paragraph|How can a writer make one point clear for one reader?|Show brief, draft, and revision.
advanced_concepts|Structure and Reader Inference|How does ordering evidence change a reader's understanding?|Compare alternative drafts and reader tests.
mysteries_unsolved_cases|A Difficult Attribution|Which evidence can identify who wrote or revised a text?|Separate style inference from records.
technology_innovation|A Writing Tool Tested|Does a tool improve clarity or merely speed?|Compare drafts, errors, and writer control.
people_personalities|A Writer's Revision Habit|What does a named writer's archive reveal?|Use drafts and correspondence, not universal lessons.
major_events|A Text Gets Rewritten|Which editor or event prompted a documented revision?|Trace version and feedback.
how_it_works|Writing as Iteration|How do planning, drafting, checking, and revision interact?|Follow one bounded piece.
rise_fall|A Style Rule Changes|Why did a convention gain or lose use?|Compare dated publishing guidance and examples.
then_vs_now|A Piece across Drafts|How did purpose, argument, and sentence shape change?|Use versioned text and notes.
future_developments|A New Writing Workflow|What outcomes should a proposed tool be tested against?|Include accuracy, authorship, access, and privacy.
myths_vs_facts|First Draft Is Finished?|What do surviving drafts show about actual process?|Use named examples, avoid universal claims.
documentary_stories|An Article's Version Trail|How did reporting, edit, fact-check, and publication proceed?|Use consented editorial artifacts.
creative_brief|Define the Reader and Task|What action or understanding should the text support?|State audience, format, and constraints.
materials_and_tools|Tool Shapes the Draft|How does pen, software, or dictation alter workflow?|Compare writer evidence and version history.
process_breakdown|Revision Decisions|Which changes address structure, evidence, tone, or mechanics?|Annotate a consented draft.
composition_choice|Opening a Piece|How does an opening set scope and expectation?|Compare reader interpretations.
collaborative_authorship|Feedback and Credit|Who contributed ideas, editing, and final decisions?|Use agreement and version records.
adaptation_across_media|Text to Script or Audio|Which ideas require restructuring for spoken delivery?|Compare versions and listener comprehension.
audience_reception|Did Readers Understand?|What did a defined audience take from a text?|Use task-based feedback, not likes alone.
cultural_context|Voice in Context|Which language and genre norms inform a choice?|Avoid declaring one dialect universally wrong.
preservation_restoration|Version Control for Writing|How can drafts and citations remain traceable?|Study a real archive or workflow.
rights_and_attribution|Borrowed Material|How are quotation, permission, and contributor credit handled?|Use jurisdiction and publication contract.
style_comparison|Two Ways to Explain|Which version helps a target reader more?|Test clarity with the same facts.
creative_failure|A Draft That Missed the Brief|What feedback revealed the mismatch?|Compare objective, reader response, and revision.
field_textual_form|Paragraph and Sentence Shape|How does layout affect comprehension?|Test same content in alternate forms.
field_performance_choice|Writing for Speech|Which phrasing works on the page but not aloud?|Use read-through and listener feedback.
field_audience_history|Changing Readers|How did a text's audience change after publication?|Track actual circulation and interpretation.
field_translation_or_adaptation|Rewriting for Another Audience|Which terms and examples need adjustment?|Preserve claim and check local understanding.
field_critical_reception|Critique of a Draft|Which comments identify evidence problems versus taste?|Use response and revision record.
"""

STUDY = """history_origins|A Study Method's Evidence History|When did one method enter teaching guidance?|Trace dated studies and scope.
famous_examples|A Study Plan Tested|What did a named intervention improve and for whom?|Read outcomes, comparator, and follow-up.
hidden_stories|Conditions around Studying|Which time, space, disability, or cost barriers are omitted?|Use learner accounts and access data.
beginner_explainers|Plan a Study Session|How can a learner choose content, retrieval, and feedback?|Use one bounded subject example.
advanced_concepts|Knowing versus Feeling Familiar|Why can rereading produce confidence without recall?|Compare prediction and delayed test.
mysteries_unsolved_cases|A Method Fails to Transfer|Which task or learner differences might explain mixed results?|Review designs and measured outcomes.
technology_innovation|A Study App Evaluated|Does it support spaced recall and useful correction?|Compare actual learner performance.
people_personalities|A Student's Adaptation|How did one learner adjust study methods to context?|Use consent and avoid universalizing.
major_events|An Exam Format Changes|How should study priorities change when assessment changes?|Compare published task criteria.
how_it_works|Study, Retrieve, Check, Adjust|How do these steps guide the next session?|Follow an illustrative schedule and feedback.
rise_fall|A Popular Study Myth Fades|Which evidence challenged a recommendation?|Trace original and review studies.
then_vs_now|A Learner over a Term|Which gains persist after weeks?|Use comparable delayed measures.
future_developments|A Personalized Study Tool|Which validation and privacy evidence would justify it?|Treat predicted gains as unproven.
myths_vs_facts|More Hours Equals More Learning?|How do strategy and prior knowledge change outcomes?|Use controlled comparison and limits.
documentary_stories|One Course's Study Redesign|How did teacher and students change practice?|Compare implementation and outcomes.
concept_sequence|Prerequisites for a Topic|Which ideas must be understood before harder problems?|Map tasks and test learner errors.
misconception|The Illusion of Mastery|What wrong prediction does a learner make about recall?|Compare confidence and later response.
worked_example|Example then Independent Problem|Does switching between model and practice help?|Use matched problem types.
retrieval_practice|Active Recall with Feedback|What can learners retrieve after a delay?|Use closed-book prompt and correction.
feedback_design|Feedback that Changes the Next Try|Which explanation helps correct a specific error?|Compare revised responses.
assessment_quality|Is the Practice Test Representative?|Does it match the skill without copying the exam?|Compare task and cognitive demand.
visual_explanation|Chart plus Words|Does combining a diagram and description improve comprehension?|Test explanation, not recognition alone.
transfer_to_new_case|Use Learning Elsewhere|Can a student solve a novel problem?|Measure transfer separately from recall.
language_access|Study in a Second Language|Which vocabulary support aids content learning?|Check comprehension and assessment fairness.
learner_variation|Different Constraints|How do disability, work, and access change feasible plans?|Avoid one-size-fits-all schedules.
source_literacy|Choose a Reliable Guide|Does a study claim reflect the population and task?|Read original research and evidence quality.
curriculum_tradeoff|What to Study First|How should time be allocated among weak and important topics?|Use feedback and assessment weights.
field_learner_misconceptions|Diagnose an Error|Which reasoning produced a wrong answer?|Collect explanation before reteaching.
field_lesson_sequence|Space and Revisit|How can key content recur after days and weeks?|Use a transparent schedule and outcomes.
field_assessment_design|Use a Diagnostic Quiz|Does a quiz reveal what needs further study?|Analyze errors and item quality.
field_memory_and_recall|Delayed Check|What remains weeks after initial learning?|Use comparable prompts and recorded baseline.
field_inclusive_learning|Flexible Study Supports|Which formats and pacing permit participation?|Test learner use and access needs.
"""


if __name__ == "__main__":
    revise_domain("451", "451_literature", LITERATURE,
                  "Literature through versioned texts, close reading, authorship, editing, translation, reception, preservation, and rights.",
                  "dated editions and manuscripts, archival catalogues, author and editor correspondence, contemporary reviews, translation records, and rights documentation",
                  "Name work, version, date, language, and passage. Distinguish textual evidence from interpretation and avoid reproducing extensive copyrighted passages.")
    revise_domain("452", "452_writing", WRITING,
                  "Writing through purpose, audience, drafts, revision, collaboration, source checking, publication, and reader comprehension.",
                  "consented versioned drafts, editorial notes, source and rights records, published text, reader feedback, and writing-instruction evidence",
                  "Name genre, audience, brief, and version. A creator's workflow is a case, not a universal prescription; preserve credit and private drafts.")
    revise_domain("453", "453_study_skills", STUDY,
                  "Study skills through realistic plans, spaced retrieval, worked examples, useful feedback, delayed measures, and varied learner constraints.",
                  "IES learning practice guides, original intervention studies, learner task data, delayed assessments, accessible materials, and implementation records",
                  "Name subject, learner group, comparator, and outcome. A short-term score or subjective familiarity does not establish durable learning for everyone.")
    rows = audit()
    print(f"Plans: {len(rows)}; reviewed question designs: {sum(r['status'] == 'editorial_question_reviewed' for r in rows)}")
